-- Resources content for Sourcework's Analyze (CLAUDE.md, "Resources stay in step with the code").
-- Content only; no schema. Rewrites the research guide, which described Extract data points and the
-- automatic background lookup.

select private.rc_release_guide(
  p_slug => 'sourcework-research',
  p_tool_key => 'transcription',
  p_title => 'Analyzing a source',
  p_summary => 'Analyze a source for the findings that add to what the project knows and a few clips worth hearing, and review them beside the transcript.',
  p_screen_keys => array['sourcework.setup', 'sourcework.source', 'sourcework.project'],
  p_sort_order => 19,
  p_version_note => 'Replaces Extract data points with Analyze',
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Analyze reads one source and tells you what in it matters: the few findings that add to what the project already knows, and a few passages that might work as audio. Everything it suggests waits for your decision, and nothing is quoted or used until you accept it."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Analyze a source"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"On the Sources tab, choose "},{"type":"text","text":"Analyze","marks":[{"type":"bold"}]},{"type":"text","text":". Each source is read on its own, up to three at a time. You can leave the page while it runs, as long as the browser tab stays open. A source that is still transcribing can be analyzed once it finishes."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"From a source, choose "},{"type":"text","text":"Analyze","marks":[{"type":"bold"}]},{"type":"text","text":" or "},{"type":"text","text":"Analyze again","marks":[{"type":"bold"}]},{"type":"text","text":" under the Data points panel."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A research question is not required. With one, the model looks for what bears on it; without one, it looks for what a reporter would need to know, check or cite. Questions on the Setup tab sharpen the result, and fewer, more specific questions work better than a list of topics."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"What you get"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Findings","marks":[{"type":"bold"}]},{"type":"text","text":": a short paraphrase with the passages it rests on, who said it, and one line on why it matters. The model is shown what the project has already accepted, so it adds to, sharpens or contradicts it instead of repeating it. Often it will find little in a source that repeats the others, and that is the intended result."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Clips to review","marks":[{"type":"bold"}]},{"type":"text","text":": a few passages that might work on the air, shown above the findings. Play one, trim it, then accept it into an ordinary excerpt or reject it. Often there are none."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Pages consulted","marks":[{"type":"bold"}]},{"type":"text","text":": the model can search the web when it needs context to read a source, such as an unfamiliar place, term or claim. The pages it relied on are listed on the Setup tab, and a search never uses an interviewee’s name. They inform the model’s reading and never count as evidence."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Set up the project"}]},{"type":"paragraph","content":[{"type":"text","text":"Open a project and select Setup, at the right of the tabs. Where this project stands is a status, not a sequence: new sources can arrive at any time."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Add the questions you are trying to answer. The ⋮ beside a question moves it up or down, or archives it. Archived questions keep their findings and can be restored."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Dismiss a page that is wrong or irrelevant and the model stops being shown it."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Say who the interviewer is"}]},{"type":"paragraph","content":[{"type":"text","text":"On a source, open the speakers menu and tick "},{"type":"text","text":"Interviewer","marks":[{"type":"bold"}]},{"type":"text","text":" beside the person asking the questions. What an interviewer says is not treated as a finding or a clip."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Review findings in the source"}]},{"type":"paragraph","content":[{"type":"text","text":"Open a source from its project and switch the panel beside the transcript from Excerpts to Data points. Each finding is underlined in lime where it is in the transcript. A dashed card and dashed underline are suggestions you have not reviewed yet."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Accept","marks":[{"type":"bold"}]},{"type":"text","text":" keeps it. "},{"type":"text","text":"Reject","marks":[{"type":"bold"}]},{"type":"text","text":" hides it, and the Rejected filter brings it back."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Edit","marks":[{"type":"bold"}]},{"type":"text","text":" rewords the claim and accepts it. The model’s own wording is kept."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Play","marks":[{"type":"bold"}]},{"type":"text","text":" listens to the passage, so you can check the paraphrase against what was said."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Analyze again later: accepted and rejected findings and clips are kept, and only suggestions you have not reviewed are replaced."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Good to know"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A finding is a paraphrase. To use the speaker’s own words, accept a clip or make an excerpt."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Interview audio and text are sent to an outside service to be read, as they are for transcription."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Everything here works on a phone: the Excerpts tab holds the switch, and the player stays docked at the bottom."}]}]}]}]}$body$
);

select private.rc_release_note(
  p_slug => 'release-2026-10-22-sourcework-analyze',
  p_tool_key => 'transcription',
  p_released_on => '2026-10-22',
  p_title => 'Sourcework: Analyze replaces Extract data points',
  p_guide_slugs => array['sourcework-research'],
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Sourcework’s Extract data points is now "},{"type":"text","text":"Analyze","marks":[{"type":"bold"}]},{"type":"text","text":". One run reads a source and returns the findings that add to what the project already has, each with a line on why it matters, a few passages that might work as audio, and the web pages the model relied on when it needed context. A research question is no longer required. The Setup tab no longer looks up background on its own; it lists the pages the model consulted while analyzing, which you can dismiss. On a source, tick Interviewer in the speakers menu so the questions are not treated as findings."}]}]}$body$
);
